{
  "root_causes": [
    {
      "service": "ts-preserve-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name, c.span_name, c.attr_status_code, count(*) n, round(approx_quantile(c.duration/1e6,0.5),1) p50_ms, round(max(c.duration/1e6),1) max_ms FROM abnormal_traces c WHERE c.service_name='ts-preserve-service' AND c.attr_span_kind='Client' AND c.span_name='POST' GROUP BY ALL",
          "claim": "In the abnormal period, preserve's outgoing POST client spans take 5 s to 130 s, with ten ending in error, versus about 12 ms normally."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'norm' p, c.service_name caller, c.span_name, count(*) n, round(approx_quantile(c.duration/1e6,0.5),1) caller_p50, round(approx_quantile(s.duration/1e6,0.5),1) travel_server_p50 FROM normal_traces c LEFT JOIN normal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id AND s.attr_span_kind='Server' WHERE c.service_name='ts-preserve-service' AND c.span_name='POST' AND c.attr_span_kind='Client' AND s.service_name='ts-travel-service' GROUP BY ALL UNION ALL SELECT 'abn', c.service_name, c.span_name, count(*), round(approx_quantile(c.duration/1e6,0.5),1), round(approx_quantile(s.duration/1e6,0.5),1) FROM abnormal_traces c LEFT JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id AND s.attr_span_kind='Server' WHERE c.service_name='ts-preserve-service' AND c.span_name='POST' AND c.attr_span_kind='Client' AND s.service_name='ts-travel-service' GROUP BY ALL",
          "claim": "Preserve's trip_detail POST to travel took 5145 ms while travel's server span took 78 ms; normally caller and callee are about 68 ms each."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name, c.attr_status_code, count(*) n, round(approx_quantile(c.duration/1e6,0.5),1) p50_ms, round(max(c.duration/1e6),1) max_ms FROM abnormal_traces c WHERE c.service_name='ts-ui-dashboard' AND c.span_name='POST /api/v1/preserveservice/preserve' AND c.attr_span_kind='Server' GROUP BY ALL",
          "claim": "User-facing ui-dashboard preserve requests now have p50 around 20 s, up from about 0.2 s, because they wait on preserve."
        },
        {
          "kind": "log",
          "sql": "SELECT level, substr(message,1,200) msg, count(*) n, min(time) t0, max(time) t1 FROM abnormal_logs WHERE service_name='ts-preserve-service' AND level IN ('SEVERE','ERROR') GROUP BY ALL ORDER BY n DESC",
          "claim": "Preserve logs SEVERE ResourceAccessException 'I/O error' on request processing, which appears only in the abnormal period."
        }
      ]
    }
  ],
